"""
Walsh-Hadamard Transform utility, adapted from SpinQuant.
Stripped to the exact bases used by LLaMA-2-7B and LLaMA-3-8B.
"""

from functools import lru_cache

import torch


def is_pow2(n: int) -> bool:
    return n > 0 and (n & (n - 1)) == 0


def get_hadK(n: int):
    hadK, K = None, None
    if n % 172 == 0:   # llama-2-7b intermediate (down_proj input)
        assert is_pow2(n // 172)
        K = 172
        hadK = get_had172()
    elif n % 28 == 0:  # llama-3-8b intermediate (14336 = 28 * 512)
        assert is_pow2(n // 28)
        K = 28
        hadK = get_had28()
    else:
        assert is_pow2(n)
        K = 1
    return hadK, K


def hadamard_transform(X: torch.Tensor) -> torch.Tensor:
    n = X.shape[-1]
    hadK, K = get_hadK(n)
    input = X.clone().view(-1, n, 1)
    output = input.clone()
    while input.shape[1] > K:
        input = input.view(input.shape[0], input.shape[1] // 2, 2, input.shape[2])
        output = output.view(input.shape)
        output[:, :, 0, :] = input[:, :, 0, :] + input[:, :, 1, :]
        output[:, :, 1, :] = input[:, :, 0, :] - input[:, :, 1, :]
        output = output.view(input.shape[0], input.shape[1], -1)
        (input, output) = (output, input)
    del output

    if K > 1:
        input = hadK.view(1, K, K).to(input) @ input

    return input.view(X.shape) / torch.tensor(n).sqrt()

